'use client';

import { FC, useLayoutEffect, useMemo, useRef } from 'react';

import classNames from 'classnames';
import { EllipsisTooltip } from '@epam/ai-dial-ui-kit';

import {
  getPivotGridMinWidth,
  getPivotGridTemplateColumns,
} from '@/src/components/Runs/Details/RowDetails/utils/pivot-column-width';
import { RowDetailSection } from '@/src/components/Runs/Details/RowDetails/models';
import { isRightAlignedRowDetailField } from '@/src/components/Runs/Details/RowDetails/utils/row-detail-alignment';
import { flattenPivotFields } from '@/src/components/Runs/Details/RowDetails/utils/flatten-pivot-fields';
import { SECTION_I18N } from '@/src/components/Runs/Details/BottomDrawer/constants';
import PivotValueCell from '@/src/components/Runs/View/RowDetails/PivotValueCell';
import { scrollPivotToField } from '@/src/components/Runs/Details/RowDetails/utils/scroll-pivot-to-field';
import { useI18n } from '@/src/locales/client';

interface Props {
  sections: RowDetailSection[];
  focusFieldKey?: string | null;
  focusRequestId?: number;
}

const HEADER_CELL_BASE = 'h-10 px-3 flex items-center bg-layer-1 border-b border-secondary dial-small-semi-text';

const ExecutionRowDetailPivotTable: FC<Props> = ({ sections, focusFieldKey, focusRequestId = 0 }) => {
  const t = useI18n();
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const columns = useMemo(() => flattenPivotFields(sections), [sections]);

  const gridTemplateColumns = useMemo(
    () => getPivotGridTemplateColumns(columns, { includeStickyLabelColumn: false }),
    [columns],
  );
  const gridMinWidth = useMemo(() => getPivotGridMinWidth(columns, { includeStickyLabelColumn: false }), [columns]);

  useLayoutEffect(() => {
    scrollPivotToField(scrollContainerRef.current, focusFieldKey);
  }, [focusFieldKey, focusRequestId, columns]);

  if (columns.length === 0) {
    return null;
  }

  return (
    <div className="relative flex flex-col flex-1 min-h-0 rounded overflow-hidden">
      <div ref={scrollContainerRef} className="flex-1 min-h-0 overflow-auto">
        <div
          className="dial-tiny-text grid w-full h-full"
          style={{
            gridTemplateColumns,
            // minmax(0, 1fr), not bare 1fr: a bare fr track can't shrink below its content's
            // min-content height, so a long cell value would blow out the row instead of
            // scrolling inside PivotValueCell.
            gridTemplateRows: 'auto auto minmax(0, 1fr)',
            minWidth: gridMinWidth,
          }}
        >
          {columns.map((column) => {
            const sectionI18nKey = SECTION_I18N[column.sectionKey];
            const sectionLabel = sectionI18nKey ? t(sectionI18nKey) : column.sectionLabel;
            return (
              <div
                key={`section-${column.sectionKey}-${column.field.fieldKey}`}
                className={classNames(HEADER_CELL_BASE, 'text-secondary', column.isSectionStart ? 'border-l' : '')}
              >
                {column.isSectionStart ? <EllipsisTooltip text={sectionLabel} className="text-secondary" /> : null}
              </div>
            );
          })}

          {columns.map((column) => (
            <div
              key={`field-${column.sectionKey}-${column.field.fieldKey}`}
              className={classNames(HEADER_CELL_BASE, 'text-secondary border-r')}
            >
              <EllipsisTooltip
                text={column.field.label}
                className={classNames('text-secondary', isRightAlignedRowDetailField(column.field) && 'text-right')}
              />
            </div>
          ))}

          {columns.map((column) => (
            <PivotValueCell key={`value-${column.sectionKey}-${column.field.fieldKey}`} field={column.field} />
          ))}
        </div>
      </div>
    </div>
  );
};

export default ExecutionRowDetailPivotTable;
import {
  ROW_DETAIL_DURATION_FIELD_KEY,
  ROW_DETAIL_HTTP_FIELD_KEY,
  ROW_DETAIL_RUN_NUMBER_FIELD_KEY,
} from '@/src/components/Runs/Details/RowDetails/constants';
import { RowDetailField } from '@/src/components/Runs/Details/RowDetails/models';

const RIGHT_ALIGNED_FIELD_KEYS = new Set<string>([
  ROW_DETAIL_RUN_NUMBER_FIELD_KEY,
  ROW_DETAIL_HTTP_FIELD_KEY,
  ROW_DETAIL_DURATION_FIELD_KEY,
]);

/**
 * Run number, HTTP status, and duration read as short right-aligned figures, unlike the panel's other
 * fields (metric values, extracted columns, request/response bodies), which stay left-aligned text.
 * Keyed on fieldKey rather than `RowDetailField.isNumeric` — that flag drives diffing and column-width
 * tiers, and disagrees with alignment here (`runNumber` is `isNumeric: false`, an index rather than a
 * value to diff numerically).
 *
 * A metric field rendered as a score value (`isScoreIndicator`) is right-aligned too, matching its grid
 * counterpart (`ScoreCellRenderer`'s columns).
 */
export const isRightAlignedRowDetailField = (field: Pick<RowDetailField, 'fieldKey' | 'isScoreIndicator'>): boolean =>
  RIGHT_ALIGNED_FIELD_KEYS.has(field.fieldKey) || field.isScoreIndicator;
export const ROW_DETAIL_SIDEBAR_CLASS = 'w-1/2 p-0';

export const ROW_DETAIL_BOTTOM_CLASS = 'p-0';

export const ROW_DETAIL_DISPLAY_PANEL_CLASS =
  'flex flex-col absolute right-0 top-0 bottom-0 w-[397px] bg-layer-3 border-l border-primary shadow-lg z-20';

export const ROW_DETAIL_PIVOT_LEFT_COL_WIDTH = 212;
export const ROW_DETAIL_PIVOT_STATUS_COL_WIDTH = 135;
export const ROW_DETAIL_PIVOT_RUN_NUMBER_COL_WIDTH = 124;
export const ROW_DETAIL_PIVOT_HTTP_COL_WIDTH = 66;
export const ROW_DETAIL_PIVOT_DURATION_COL_WIDTH = 140;
export const ROW_DETAIL_PIVOT_SCORE_COL_WIDTH = 124;
export const ROW_DETAIL_PIVOT_DEFAULT_COL_WIDTH = 200;
export const ROW_DETAIL_PIVOT_TEXT_COL_WIDTH = 320;

export const ROW_DETAIL_EXECUTION_SECTION_KEY = 'execution';
export const ROW_DETAIL_RUN_NUMBER_FIELD_KEY = 'runNumber';
export const ROW_DETAIL_HTTP_FIELD_KEY = 'httpStatusCode';
export const ROW_DETAIL_DURATION_FIELD_KEY = 'execDurationMs';
export const ROW_DETAIL_REQUEST_BODY_FIELD_KEY = 'requestBody';
export const ROW_DETAIL_RESPONSE_BODY_FIELD_KEY = 'responseBody';
export const ROW_DETAIL_RUN_NUMBER_LABEL = '# Run number';
export const ROW_DETAIL_HTTP_LABEL = 'HTTP';

/** Execution Result pivot defaults — Duration hidden; Request/Response bodies visible. */
export const EXECUTION_RESULT_DEFAULT_HIDDEN_FIELDS = new Set<string>([ROW_DETAIL_DURATION_FIELD_KEY]);

