 * missing score (a dash) does not flip the column to the left. Only a metric that actually carries a
 * non-numeric value stays left-aligned text.
 */
export const isRightAlignedRowDetailField = (
  field: Pick<RowDetailField, 'fieldKey' | 'isScoreIndicator' | 'isNumeric' | 'isMetric' | 'primaryRaw' | 'secondaryRaw'>,
): boolean => {
